/**
 * Redis Configuration — Connection and client setup
 * Used for: rate limiting, session store, caching, token blacklist
 * Generated by BackendForge
 */

const { createClient } = require('redis');
const { env } = require('./env');
const winston = require('winston');

const logger = winston.createLogger({ level: env.LOG_LEVEL });

let redisClient = null;

const connectRedis = async () => {
  try {
    redisClient = createClient({
      url: env.REDIS_URL,
      socket: {
        reconnectStrategy: (retries) => {
          if (retries > 10) {
            logger.error('Redis: Max reconnection attempts reached');
            return new Error('Max reconnection attempts reached');
          }
          return Math.min(retries * 100, 3000);
        },
      },
    });

    redisClient.on('error', (err) => {
      logger.error(`Redis error: ${err.message}`);
    });

    redisClient.on('connect', () => {
      logger.info('Redis connected');
    });

    redisClient.on('reconnecting', () => {
      logger.warn('Redis reconnecting...');
    });

    await redisClient.connect();
    return redisClient;
  } catch (error) {
    logger.warn(`Redis connection failed: ${error.message} — continuing without cache`);
    return null;
  }
};

const getRedisClient = () => redisClient;

const disconnectRedis = async () => {
  if (redisClient) {
    await redisClient.quit();
    logger.info('Redis disconnected');
  }
};

module.exports = { connectRedis, getRedisClient, disconnectRedis };
